with kept_keys as (select city from customers except all select city from customers where email is not null), reconciled as (select s.* from customers s join kept_keys k on s.city = k.city) select city, date_trunc('week', signup_date) as week_start, count_if(country = 'UK') as uk_events, sum(age) filter (where country = 'JP') as jp_total_age, dense_rank() over (partition by city order by count_if(country = 'UK') desc) as uk_events_dense_rank from reconciled group by city, week_start
